VALUES
  (1, 3, NULL, 1, 1, 2, 1.5, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'FDA seafood storage guidance', 'https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely', NULL, '1-2 days (category fallback)', 'Use only when image recognition identifies the category but not a catalogue product.'),
  (2, 3, NULL, 2, 60, 240, 150, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'FoodSafety.gov cold chart', 'https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts', NULL, '60-240 days (category fallback)', 'Use only when image recognition identifies the category but not a catalogue product.'),
  (3, 5, NULL, 3, 2, 10, 6, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'USDA FoodKeeper open data', 'https://catalog.data.gov/dataset/fsis-foodkeeper-data', NULL, '2-10 days (category fallback)', 'Use only when image recognition identifies the category but not a catalogue product.'),
  (4, 5, NULL, 1, 2, 21, 11.5, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'USDA FoodKeeper open data', 'https://catalog.data.gov/dataset/fsis-foodkeeper-data', NULL, '2-21 days (category fallback)', 'Use only when image recognition identifies the category but not a catalogue product.'),
  (5, 5, NULL, 2, 30, 365, 197.5, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'USDA FoodKeeper open data', 'https://catalog.data.gov/dataset/fsis-foodkeeper-data', NULL, '30-365 days (category fallback)', 'Use only when image recognition identifies the category but not a catalogue product.'),
  (6, 3, NULL, 3, 0, 0, NULL, 'NOT_RECOMMENDED', 'HIGH', 'CATEGORY_GENERALIZATION', 'NOT_RECOMMENDED; FDA maximum 2 hours', 'https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely', NULL, 'Maximum 2 hours at 25-30 C; room-temperature storage is not recommended.', 'Display a warning; do not calculate an endorsed room-temperature expiry date.'),
  (7, 2, NULL, 1, 1, 5, 3, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'FoodSafety.gov Cold Food Storage Chart', 'https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts', 'Raw sausage and ground meat: 1-2 days; fresh steaks, chops and roasts: 3-5 days refrigerated at 4 C or below', '1-5 days refrigerator category range', 'Category fallback for unidentified raw meat; use a product-specific rule when available.'),
  (8, 2, NULL, 2, 30, 365, 197.5, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'FoodSafety.gov Cold Food Storage Chart', 'https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts', 'Raw meat ranges from about 1 month for bacon to 12 months for selected fresh cuts/poultry at -18 C or below', '1-12 months converted to 30-365 days', 'Freezer durations are quality guidance; category fallback only.'),
  (9, 2, NULL, 3, 0, 0, NULL, 'NOT_RECOMMENDED', 'HIGH', 'CATEGORY_GENERALIZATION', 'FDA two-hour rule for perishable food', 'https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely', 'Never leave seafood or other perishable food out of refrigeration for more than 2 hours', 'Maximum 2 hours; storage at 25-30 C is not recommended', 'Display a warning; do not calculate an endorsed pantry expiry date.'),
  (10, 4, NULL, 1, 2, 14, 8, 'AVAILABLE', 'MEDIUM', 'CATEGORY_GENERALIZATION', 'University of Georgia Extension, Quick Storage Guide for Vegetable Crops', 'https://fieldreport.caes.uga.edu/publications/C1205/quick-storage-guide-for-vegetable-crops/', 'Storage-life table: leafy greens 14 days at 41 F; squash under 10 days; cucumber under 14 days; conditions differ by commodity', 'Conservative 2-14 day refrigerator category range', 'Highly product-dependent category fallback; use a product-specific rule when available.'),
  (11, 4, NULL, 2, 240, 360, 300, 'AVAILABLE', 'HIGH', 'CATEGORY_GENERALIZATION', 'National Center for Home Food Preservation frozen-food guidance', 'https://nchfp.uga.edu/how/freeze/freeze-general-information/how-long-can-i-store-frozen-foods/', 'Fruits and vegetables: approximately 8-12 months at 0 F (-18 C)', '8-12 months converted to 240-360 days', 'Quality guidance; vegetables should be prepared and blanched as appropriate before freezing.'),
  (12, 4, NULL, 3, 1, 7, 4, 'AVAILABLE', 'MEDIUM', 'CATEGORY_GENERALIZATION', 'University of Georgia Extension, Quick Storage Guide for Vegetable Crops', 'https://fieldreport.caes.uga.edu/publications/C1205/quick-storage-guide-for-vegetable-crops/', 'Storage-life table and post-harvest section: ambient holding time depends on commodity and temperature; refrigerate when unknown', 'Conservative 1-7 day pantry category range', 'Highly product-dependent category fallback at the Malaysia 25-30 C profile; refrigerate when the exact vegetable is unknown.'),
